using UnityEngine;
using UnityEngine.UI;
public static class CampaignGuide {
    static GameObject panel;
    static readonly string[] Titles={"Your campaign","Preparation and repeat preparation","Ottoman actions","Spies, research and relief"};
    static readonly string[] Pages={
        "<b>Before the siege</b>\nBegin in January 1452. Dated events anchor the calendar; flexible months let you choose one preparation from the available pool. You cannot complete every project. Some preparations require career achievements earned across campaigns.\n\n<b>A siege day</b>\nInspect the council screens and make affordable minor purchases. A major action, or resting, ends management. Resolve the day's event, then read the Ottoman report. An assault may require a decision at the breach. Advancing the calendar consumes food and advances incoming aid and other timed consequences.\n\n<b>Holding the walls</b>\nRepairs preserve the current line. If an assault breaches it, enough Varangians can hold the breach at the stated cost; otherwise the defenders fall back. Losing the last defensive line ends the campaign. Protect your own health as well as the army.\n\nSpace / Enter advances narrative text. Escape returns or opens the campaign menu. Checkpoints resume at management.",
        "<b>Choosing preparations</b>\nEach flexible slot spends a month on one available preparation. Fixed milestones still occur on their dates. A preparation normally leaves the pool after selection; read its conditions and costs before committing. Achievement locks refer to your main-menu career achievements, not accomplishments in another event.\n\n<b>Repeat preparation = restart at the siege</b>\nWhen you reach the siege, the game records a preparation snapshot. This menu option loads that snapshot: the resulting forces, resources, decisions and relationships. It skips the preparation months rather than making you choose them again. Later siege losses and gains are not carried back into it.\n\nTo change your preparation decisions, choose New campaign. To resume your latest progress, choose Continue checkpoint. A later campaign that reaches the siege replaces the stored preparation snapshot.",
        "<b>Bombardment</b> — Each Ottoman cannon removes one percentage point from the current wall.\n<b>Fill the moat</b> — Labourers reduce the moat's protection by roughly 9–20 points.\n<b>Build a ramp</b> — The siege ramp gains 10–20 points of progress.\n<b>Build tower / ram</b> — The corresponding siege engine becomes available to the enemy.\n<b>Bring another cannon</b> — Ottoman artillery increases by one.\n<b>Assault</b> — Balkan troops, irregulars or Janissaries attack. The battle report shows losses and whether a breach needs your decision.\n<b>Secure provisions</b> — When Ottoman stores run out, they spend the day resupplying instead of attacking; 1% of remaining irregulars desert and 15 days of stores arrive.\n<b>Attack Galata</b> — Possible when Galata is held by you or Giovanni; its defences face a separate attack.\n<b>Operations delayed</b> — No Ottoman land action that turn. Remaining delay drops by one; food consumption and naval pressure continue.\n<b>No major operation completed</b> — No named land operation resolved. This does not imply hidden reinforcements or foraging.\n\nThe enemy chooses tactics according to the moat and current wall condition. Read the actual daily report rather than assuming every quiet day has the same cause.",
        "<b>Enemy camp alert</b>\nThis is Ottoman counter-intelligence awareness, from 0 to 100%. Zero means the camp is not alerted; it does not mean your missions cannot fail. Operations show their alert increase and agent-loss risk before you commit.\n\n<b>The siege-opening infiltration</b>\nThe 5,000-gold mission seeks local informants. The size of the resulting network is uncertain; the outcome reports the agents recruited and your new total. Other intelligence preparations have their own stated rewards.\n\n<b>Research</b>\nSecrets pay for research. An active technology is highlighted in gold and remains in effect; it cannot be purchased twice. Read its effect to see what it changes.\n\n<b>Committed relief</b>\nA request can be declined. Accepted expeditions appear in Diplomacy with their full promised cargo and days until arrival. The briefing identifies the next arrival and counts all committed expeditions. Expediting an accepted expedition spends gold to shorten its remaining journey."
    };
    public static void Show(Transform parent,int page=0) {
        if(panel!=null)Object.Destroy(panel);
        panel=CampaignHUD.Panel(parent,"Campaign guide",new Vector2(.06f,.04f),new Vector2(.94f,.96f));ImperialTheme.Panel(panel);
        CampaignHUD.Label(panel.transform,"How to play · "+Titles[page],new Vector2(.04f,.87f),new Vector2(.96f,.97f),34);
        var viewport=CampaignHUD.Panel(panel.transform,"Reading area",new Vector2(.04f,.14f),new Vector2(.94f,.85f));viewport.AddComponent<RectMask2D>();
        var content=new GameObject("Guide text",typeof(RectTransform));content.transform.SetParent(viewport.transform,false);var r=content.GetComponent<RectTransform>();r.anchorMin=new Vector2(0,1);r.anchorMax=Vector2.one;r.pivot=new Vector2(.5f,1);r.sizeDelta=new Vector2(0,page==2?1100:900);
        CampaignHUD.Label(content.transform,Pages[page],new Vector2(.02f,.01f),new Vector2(.97f,.99f),26);
        var scroll=viewport.AddComponent<ScrollRect>();scroll.content=r;scroll.viewport=viewport.GetComponent<RectTransform>();scroll.horizontal=false;scroll.scrollSensitivity=45;scroll.movementType=ScrollRect.MovementType.Clamped;
        CampaignHUD.AddScrollbar(scroll,panel.transform,new Vector2(.95f,.14f),new Vector2(.965f,.85f));
        CampaignHUD.MakeButton(panel.transform,"Previous",new Vector2(.05f,.035f),new Vector2(.28f,.11f),()=>Show(parent,(page+3)%4));
        CampaignHUD.MakeButton(panel.transform,"Return",new Vector2(.38f,.035f),new Vector2(.62f,.11f),()=>Object.Destroy(panel));
        CampaignHUD.MakeButton(panel.transform,"Next",new Vector2(.72f,.035f),new Vector2(.95f,.11f),()=>Show(parent,(page+1)%4));
    }
}
